/**
 * Shared building blocks used by every family: neutral footwork (bounce,
 * plant, sway, groove), resting arms, turns, and torso / head accents, plus
 * the idle groove. Owned by the catalogue maintainer; family authors use these
 * ids but do not edit this file.
 */

import { ARM, mir, wide, W, FIST, type PoseSpec, type ArmAngles } from '../poseKit';
import { hand } from '../../coach/poses';
import { full, type MoveDef, type PatternSet } from '../catalog';

const swayA: PoseSpec = { x: 0.03, hips: 0.03, lf: [-W, 0.015, 0.01], lean: 2, head: -3 };
const hipSwayA: PoseSpec = { hips: 0.074, tilt: 7, y: -0.038, x: 0.012, lf: [-0.085, 0.024, 0.04], kneeL: -0.16, lean: 3, head: -4 };

// Turns: on the balls of the feet, close stance, one foot lifting off the floor.
// SPIN interpolates linearly and the short way round: keep keys < 180 deg apart.
const TURN_FEET: PoseSpec = { rf: [0.055, 0, 0], lf: [-0.055, 0, 0], pitchR: 18, pitchL: 18 };
/** A 360 over beats start .. start+2 (lands on the next key at 0 / 360). */
export const spinKeys = (start: number, hips = 0): (readonly [number, PoseSpec])[] => [
  [start, { ...TURN_FEET, y: -0.06, spin: 0, hips: hips * 0.5, kneeR: 0.1, kneeL: 0.1 }],
  [start + 0.5, { ...TURN_FEET, y: -0.02, spin: 60, hips: -hips }],
  [start + 1, { rf: [0.05, 0.05, 0.03], lf: [-0.055, 0, 0], y: -0.01, spin: 165, hips }],
  [start + 1.5, { ...TURN_FEET, y: -0.035, spin: 270, hips: -hips }],
];

const HUG: ArmAngles = hand(-0.07, -0.05, 0.13, [0.9, -0.6, -0.3]);
const chestA: PoseSpec = { chestX: 0.05, lean: -3, head: 3 };
const leanA: PoseSpec = { lean: 8, head: -5 };
const lookA: PoseSpec = { turn: 22, head: 4 };

